code='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    colors = {v for row in g for v in row if v != bg}
    wall = None
    runs = []
    for c in (0, w - 1):
        vals = [g[r][c] for r in range(h)]
        for color in colors:
            start = None
            for r in range(h + 1):
                if r < h and vals[r] == color:
                    if start is None: start = r
                elif start is not None:
                    if r - start >= 2:
                        runs.append((color, c, start, r - 1))
                    start = None
    if not runs:
        return g
    wall = max(set(x[0] for x in runs), key=lambda color: sum(1 for x in runs if x[0] == color))
    runs = [x for x in runs if x[0] == wall]
    marker_colors = colors - {wall}
    marker = max(marker_colors, key=lambda color: sum(v == color for row in g for v in row))
    points = [(r,c) for r in range(h) for c in range(w) if g[r][c] == marker]
    source = next((seg for seg in runs if any(seg[2] <= r <= seg[3] for r,c in points)), None)
    if source is None:
        return g
    _, sc, s0, s1 = source
    for r,c in points:
        if not (s0 <= r <= s1):
            continue
        g[r][c] = 4
        step = 1 if sc == 0 else -1
        x = c + step
        while 0 <= x < w and x != sc:
            g[r][x] = marker
            x += step
    for _, tc, t0, t1 in runs:
        if (tc,t0,t1) == (sc,s0,s1):
            continue
        for r,c in points:
            if s0 <= r <= s1:
                rr = t0 + (r - s0)
                if t0 <= rr <= t1:
                    lo, hi = sorted((tc, (w-1 if tc == 0 else 0)))
                    for x in range(lo, hi+1):
                        if x != tc:
                            g[rr][x] = marker
    return g
'''
